int dvb_frontend_send_diseqc_msg(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int ret;

	/* Validate the length of the DiSEqC message */
	if (d->msg[0] < 3 || d->msg[0] > 6) {
		return -EINVAL;
	}

	/* Log the message if debugging is enabled */
#ifdef DVB_FE_DEBUG
	dvb_frontend_log(fe, "Sending DiSEqC message: %*ph\n", d->msg[0], d->msg);
#endif

	/* Prepare the message for transmission, including handling toneburst conditions */
	ret = dvb_frontend_prepare_diseqc(fe, d);
	if (ret < 0)
		return ret;

	/* Wait for the LNB to be ready */
	ret = dvb_frontend_wait_for_lnb_ready(fe);
	if (ret < 0)
		return ret;

	/* Introduce a delay for voltage stabilization */
	udelay(DVB_FE_VOLTAGE_STABILIZATION_DELAY);

	/* Execute the command to send the message */
	ret = dvb_frontend_execute_diseqc(fe, d);
	if (ret < 0)
		return ret;

	/* Wait for the transmission to complete */
	ret = dvb_frontend_wait_for_transmission_complete(fe);
	if (ret < 0)
		return ret;

	return 0;
}

