		d->msg[0] != 0x70 && d->msg[0] != 0x71 &&
		d->msg[0] != 0x72 && d->msg[0] != 0x73 &&
		d->msg[0] != 0x74 && d->msg[0] != 0x75 &&
		d->msg[0] != 0x76 && d->msg[0] != 0x77 &&
		d->msg[0] != 0x78 && d->msg[0] != 0x79 &&
