int dvb_frontend_send_diseqc_msg(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int ret;

	if (d->msg_len < 1 || d->msg_len > 6)
		return -EINVAL;

	if (debug)
		dvb_diseqc_dump(d->msg, d->msg_len);

	ret = dvb_frontend_prepare_diseqc(fe, d);
	if (ret)
		return ret;

	ret = dvb_frontend_wait_for_lnb_ready(fe);
	if (ret)
		return ret;

	msleep(10); /* Wait for voltage to stabilize */

	ret = dvb_frontend_execute_diseqc(fe, d);
	if (ret)
		return ret;

	ret = dvb_frontend_wait_for_tx_complete(fe);
	if (ret)
		return ret;

	return 0;
}

int send_diseqc_message(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int result = 0;

	/* Validate DiSEqC message length */
	if (d->msg[0] < 0x20 || d->msg[0] > 0x2f) {
		return -EINVAL;
	}

	/* Log message if debugging is enabled */
#ifdef DVB_FE_DEBUG
	printk(KERN_DEBUG "DiSEqC message: %*ph\n", d->msg[0], d->msg);
#endif

	/* Prepare message for transmission (handle toneburst) */
	if (d->msg[0] >= 0x24 && d->msg[0] <= 0x27) {
		/* Toneburst required */
		if (fe->ops.set_toneburst)
			result = fe->ops.set_toneburst(fe, 1);
		if (result < 0)
			return result;
	}

	/* Wait for LNB to be ready */
	if (fe->ops.wait_for_lnb_ready) {
		result = fe->ops.wait_for_lnb_ready(fe);
		if (result < 0)
			return result;
	}

	/* Delay for voltage stabilization */
	msleep(50);

	/* Send the DiSEqC message */
	if (fe->ops.send_master_cmd) {
		result = fe->ops.send_master_cmd(fe, d);
		if (result < 0)
			return result;
	}

	/* Wait for transmission to complete */
	msleep(100);

	return result;
}

int dvb_frontend_send_diseqc_msg(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int ret;

	if (d->msg_len < 2 || d->msg_len > 6) {
		dvb_frontend_warn(fe, "invalid DiSEqC message length (%d)\n", d->msg_len);
		return -EINVAL;
	}

	dvb_frontend_dbg(fe, "sending DiSEqC msg: ");
	for (int i = 0; i < d->msg_len; i++)
		dvb_frontend_dbg(fe, "%02x ", d->msg[i]);
	dvb_frontend_dbg(fe, "\n");

	if ((fe->ops.send_master_cmd) && (fe->ops.send_master_cmd != NULL)) {
		ret = fe->ops.send_master_cmd(fe, d, NULL);
		if (ret < 0)
			dvb_frontend_warn(fe, "failed to send DiSEqC command\n");
	} else {
		ret = -EOPNOTSUPP;
		dvb_frontend_warn(fe, "DiSEqC master command not supported by frontend\n");
	}

	return ret;
}
